<?php
/**
 * SARMAD Attendance - one-time device activation codes.
 *
 * A code is generated by the OWNER panel (or by an owner level reset) and is
 * printed/typed on the kiosk exactly once. Only the SHA-256 hash is stored, so
 * a database leak can not be replayed against /api/v1/device/activate.
 *
 * Rules enforced here (all of them are server side, the UI only mirrors them):
 *   - one active code per device: issuing a new one revokes the old ones,
 *   - time limited (default 60 minutes),
 *   - attempt limited (default 10 wrong tries -> code burns out),
 *   - single use (used_at is set inside the same transaction as the token),
 *   - bound to exactly one device_id + customer_id pair, so a code can never
 *     activate a different device or leak into another tenant.
 */

declare(strict_types=1);

namespace App\Models;

use App\Core\Database;
use App\Core\Security;

final class DeviceActivationCode extends Model
{
    protected static string $table = 'device_activation_codes';

    public const DEFAULT_TTL_MINUTES = 60;
    public const DEFAULT_MAX_ATTEMPTS = 10;

    /* -----------------------------------------------------------------
     * Issuing
     * ----------------------------------------------------------------*/

    /**
     * Create a new one-time code for a device and return the PLAIN code once.
     *
     * @return array{code:string, prefix:string, expires_at:string, device_id:int, customer_id:int}
     */
    public static function issue(int $deviceId, int $customerId, int $createdBy = 0, ?int $ttlMinutes = null): array
    {
        $ttl = max(5, (int) ($ttlMinutes ?? self::DEFAULT_TTL_MINUTES));

        self::revokeForDevice($deviceId, 'replaced');

        $code      = Security::deviceCode();
        $expiresAt = date('Y-m-d H:i:s', time() + ($ttl * 60));

        self::create([
            'uuid'         => Security::uuid4(),
            'device_id'    => $deviceId,
            'customer_id'  => $customerId,
            'code_hash'    => Security::hashToken(self::normalize($code)),
            'code_prefix'  => substr(self::normalize($code), 0, 4),
            'attempts'     => 0,
            'max_attempts' => self::DEFAULT_MAX_ATTEMPTS,
            'expires_at'   => $expiresAt,
            'created_by'   => $createdBy,
        ]);

        return [
            'code'        => $code,
            'prefix'      => substr(self::normalize($code), 0, 4),
            'expires_at'  => $expiresAt,
            'device_id'   => $deviceId,
            'customer_id' => $customerId,
        ];
    }

    /**
     * Kill every open code of a device (driver: owner reset, revoke, delete).
     */
    public static function revokeForDevice(int $deviceId, string $reason = 'revoked'): int
    {
        return (int) Database::run(
            'UPDATE `' . self::tableName() . '`'
            . ' SET `revoked_at` = NOW() WHERE `device_id` = ? AND `used_at` IS NULL AND `revoked_at` IS NULL',
            [$deviceId]
        )->rowCount();
    }

    /* -----------------------------------------------------------------
     * Verification
     * ----------------------------------------------------------------*/

    /**
     * Codes are typed by hand on a tablet keyboard, so they are normalised the
     * same way they were produced (upper case, no spaces/dashes).
     */
    public static function normalize(string $code): string
    {
        $code = strtoupper(trim($code));
        $code = str_replace([' ', '-', '_', '.'], '', $code);

        return substr($code, 0, 32);
    }

    /**
     * Verify a plain code and return the actionable result.
     *
     * The returned array always carries a machine readable `code` so the API
     * layer can answer with the documented error code without re-implementing
     * the rules.
     *
     * @return array{ok:bool, code:string, message:string, row?:array<string,mixed>}
     */
    public static function verify(string $plainCode): array
    {
        $normalized = self::normalize($plainCode);

        if ($normalized === '') {
            return ['ok' => false, 'code' => 'ACTIVATION_CODE_REQUIRED', 'message' => 'کد فعال‌سازی را وارد کنید.'];
        }

        $row = self::findBy('code_hash', Security::hashToken($normalized));

        if ($row === null) {
            return ['ok' => false, 'code' => 'ACTIVATION_CODE_INVALID', 'message' => 'کد فعال‌سازی نامعتبر است.'];
        }

        if ((string) ($row['revoked_at'] ?? '') !== '') {
            return ['ok' => false, 'code' => 'ACTIVATION_CODE_REVOKED', 'message' => 'این کد فعال‌سازی باطل شده است.', 'row' => $row];
        }

        if ((string) ($row['used_at'] ?? '') !== '') {
            return ['ok' => false, 'code' => 'ACTIVATION_CODE_USED', 'message' => 'این کد فعال‌سازی قبلاً استفاده شده است.', 'row' => $row];
        }

        if (strtotime((string) $row['expires_at']) < time()) {
            return ['ok' => false, 'code' => 'ACTIVATION_CODE_EXPIRED', 'message' => 'کد فعال‌سازی منقضی شده است. کد جدید بگیرید.', 'row' => $row];
        }

        if ((int) $row['attempts'] >= (int) $row['max_attempts']) {
            return ['ok' => false, 'code' => 'ACTIVATION_CODE_LOCKED', 'message' => 'تعداد تلاش‌های ناموفق زیاد است. کد جدید بگیرید.', 'row' => $row];
        }

        return ['ok' => true, 'code' => 'OK', 'message' => 'کد فعال‌سازی معتبر است.', 'row' => $row];
    }

    /**
     * Count one wrong try against every open code of a device (used when a
     * guess shares the prefix of an open code, so the attacked device is known)
     * so brute force burns the code out instead of trying forever.
     */
    public static function registerFailedAttempt(int $deviceId): void
    {
        Database::run(
            'UPDATE `' . self::tableName() . '` SET `attempts` = `attempts` + 1'
            . ' WHERE `device_id` = ? AND `used_at` IS NULL AND `revoked_at` IS NULL',
            [$deviceId]
        );
    }

    /**
     * Count one try against a specific code row (it was recognised but refused:
     * already used, expired or revoked). Keeps the owner-visible counter honest.
     */
    public static function registerAttemptById(int $codeId): void
    {
        Database::run(
            'UPDATE `' . self::tableName() . '` SET `attempts` = `attempts` + 1 WHERE `id` = ?',
            [$codeId]
        );
    }

    /**
     * Which device is behind a code prefix? Used to charge a failed guess to the
     * right device when the first 4 characters match an open code.
     */
    public static function deviceIdForPrefix(string $prefix): ?int
    {
        $prefix = substr(self::normalize($prefix), 0, 4);

        if ($prefix === '') {
            return null;
        }

        $row = Database::selectOne(
            'SELECT `device_id` FROM `' . self::tableName() . '`'
            . ' WHERE `code_prefix` = ? AND `used_at` IS NULL AND `revoked_at` IS NULL'
            . ' ORDER BY `id` DESC LIMIT 1',
            [$prefix]
        );

        return $row === null ? null : (int) $row['device_id'];
    }

    /**
     * Burn the code. The WHERE clause makes the UPDATE itself the single use
     * lock: two parallel activations can not both consume the same code.
     */
    public static function consume(int $codeId, string $ip): bool
    {
        $affected = (int) Database::run(
            'UPDATE `' . self::tableName() . '`'
            . ' SET `used_at` = NOW(), `used_ip` = ?'
            . ' WHERE `id` = ? AND `used_at` IS NULL AND `revoked_at` IS NULL',
            [substr($ip, 0, 45), $codeId]
        )->rowCount();

        return $affected === 1;
    }

    /* -----------------------------------------------------------------
     * Reading
     * ----------------------------------------------------------------*/

    /**
     * @return array<string,mixed>|null
     */
    public static function openForDevice(int $deviceId): ?array
    {
        return Database::selectOne(
            'SELECT * FROM `' . self::tableName() . '`'
            . ' WHERE `device_id` = ? AND `used_at` IS NULL AND `revoked_at` IS NULL'
            . ' ORDER BY `id` DESC LIMIT 1',
            [$deviceId]
        );
    }

    /**
     * Activation state shown in the panels (never the code itself).
     *
     * @return array{state:string, prefix:string, expires_at:?string, attempts:int}
     */
    public static function stateForDevice(int $deviceId): array
    {
        $row = self::openForDevice($deviceId);

        if ($row === null) {
            return ['state' => 'none', 'prefix' => '', 'expires_at' => null, 'attempts' => 0];
        }

        $expired = strtotime((string) $row['expires_at']) < time();

        return [
            'state'      => $expired ? 'expired' : 'open',
            'prefix'     => (string) $row['code_prefix'],
            'expires_at' => (string) $row['expires_at'],
            'attempts'   => (int) $row['attempts'],
        ];
    }

    /**
     * Same as stateForDevice() for a whole page of devices, in ONE query
     * (the owner list shows 20 devices per page).
     *
     * @param array<int,int> $deviceIds
     * @return array<int,array{state:string, prefix:string, expires_at:?string, attempts:int}>
     */
    public static function statesForDevices(array $deviceIds): array
    {
        $ids = array_values(array_unique(array_filter(array_map('intval', $deviceIds), static fn (int $id): bool => $id > 0)));

        if ($ids === []) {
            return [];
        }

        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $rows = Database::select(
            'SELECT `device_id`, `code_prefix`, `expires_at`, `attempts`, `used_at`, `revoked_at`'
            . ' FROM `' . self::tableName() . '`'
            . ' WHERE `device_id` IN (' . $placeholders . ') ORDER BY `id` DESC',
            $ids
        );

        $states = [];

        foreach ($rows as $row) {
            $deviceId = (int) $row['device_id'];

            // The first row per device is the newest one (ORDER BY id DESC).
            if (isset($states[$deviceId])) {
                continue;
            }

            if ($row['used_at'] !== null || $row['revoked_at'] !== null) {
                $states[$deviceId] = [
                    'state'      => $row['used_at'] !== null ? 'used' : 'revoked',
                    'prefix'     => (string) $row['code_prefix'],
                    'expires_at' => (string) $row['expires_at'],
                    'attempts'   => (int) $row['attempts'],
                ];

                continue;
            }

            $states[$deviceId] = [
                'state'      => strtotime((string) $row['expires_at']) < time() ? 'expired' : 'open',
                'prefix'     => (string) $row['code_prefix'],
                'expires_at' => (string) $row['expires_at'],
                'attempts'   => (int) $row['attempts'],
            ];
        }

        return $states;
    }

    public static function openCount(): int
    {
        return (int) Database::scalar(
            'SELECT COUNT(*) FROM `' . self::tableName() . '`'
            . ' WHERE `used_at` IS NULL AND `revoked_at` IS NULL AND `expires_at` > NOW()'
        );
    }
}
